I have enough to answer. The evidence points to one origin, ts-route-plan-service, whose slowness propagates to travel-plan and then to the ui-dashboard. Route-plan's CPU is not saturated, and the hotspot is its own method.

```json
{
  "root_causes": [
    {
      "service": "ts-route-plan-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Internal' GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Internal' GROUP BY 1,2 ORDER BY 2,1",
          "claim": "Route-plan's internal RoutePlanController methods slowed: getMinStopStations p95 about 697ms normal vs 5750ms abnormal."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, avg(value) avgv, max(value) maxv FROM abnormal_metrics WHERE service_name='ts-route-plan-service' AND metric IN ('container.cpu.usage','jvm.cpu.recent_utilization') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, avg(value), max(value) FROM normal_metrics WHERE service_name='ts-route-plan-service' AND metric IN ('container.cpu.usage','jvm.cpu.recent_utilization') GROUP BY 1,2",
          "claim": "Route-plan's own container and JVM CPU are flat or lower during the incident, so it is not CPU-saturated."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, p.service_name, c.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 p95ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id WHERE p.service_name='ts-route-plan-service' AND p.attr_span_kind='Internal' GROUP BY 1,2,3 UNION ALL SELECT 'norm', p.service_name, c.service_name, count(*), approx_quantile(c.duration,0.95)/1e6 FROM normal_traces p JOIN normal_traces c ON c.parent_span_id=p.span_id WHERE p.service_name='ts-route-plan-service' AND p.attr_span_kind='Internal' GROUP BY 1,2,3",
          "claim": "Route-plan's internal time is spent in its downstream calls to travel, travel2 and route services, which also slowed."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, c.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 p95ms FROM abnormal_traces p JOIN abnormal_traces s ON s.parent_span_id=p.span_id JOIN abnormal_traces c ON c.span_id=s.span_id WHERE p.service_name='ts-travel-plan-service' AND p.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' GROUP BY 1,2 UNION ALL SELECT 'norm', c.service_name, count(*), approx_quantile(c.duration,0.95)/1e6 FROM normal_traces p JOIN normal_traces s ON s.parent_span_id=p.span_id JOIN normal_traces c ON c.span_id=s.span_id WHERE p.service_name='ts-travel-plan-service' AND p.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "Travel-plan's client calls to route-plan slowed: p95 about 596ms normal vs 2305ms abnormal."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95ms FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name IN ('ts-ui-dashboard','ts-travel-plan-service') AND span_name LIKE '%travelPlan%' GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, span_name, count(*), approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE attr_span_kind='Server' AND service_name IN ('ts-ui-dashboard','ts-travel-plan-service') AND span_name LIKE '%travelPlan%' GROUP BY 1,2,3",
          "claim": "User-facing ui-dashboard travelPlan requests slowed to about 20 s p95, matching travel-plan's server latency."
        }
      ]
    }
  ]
}
```

